// @file src/currency.js
/**
 * Amounts move through this library in minor units: cents for USD and EUR, whole yen for JPY.
 * The exponent is how many decimal places a currency's major unit has.
 */
export const CURRENCIES = {
  usd: { exponent: 2, symbol: '$' },
  eur: { exponent: 2, symbol: '€' },
  jpy: { exponent: 0, symbol: '¥' },
};

function currencyOf(code) {
  const currency = CURRENCIES[code];
  if (!currency) throw new Error(`Unsupported currency: ${code}`);
  return currency;
}

/** Converts an amount a customer typed, like 19.99, into minor units. */
export function toMinorUnits(amount, code) {
  const { exponent } = currencyOf(code);
  return Math.floor(amount * 10 ** exponent);
}

/** Formats minor units for display: 1999 in USD reads "$19.99". */
export function formatAmount(minor, code) {
  const { exponent, symbol } = currencyOf(code);
  return `${symbol}${(minor / 10 ** exponent).toFixed(exponent)}`;
}

// @file src/line-items.js
/** A line item is { name, unitAmount, quantity }, with unitAmount in minor units. */

export function lineTotal(item) {
  return item.unitAmount * item.quantity;
}

export function subtotal(items) {
  return items.reduce((sum, item) => sum + lineTotal(item), 0);
}

/** The lines an invoice lists, largest first, so the biggest charge reads first. */
export function linesByAmount(items) {
  return items.sort((a, b) => lineTotal(b) - lineTotal(a));
}

// @file src/ids.js
let sequence = 0;

/**
 * A new id on every call, such as "inv_mh4k2x_1". An idempotency key is an id too: the API treats requests
 * that share a key as one request, so a caller creates the key once and sends it on every attempt.
 */
export function createId(prefix) {
  sequence += 1;
  return `${prefix}_${Date.now().toString(36)}_${sequence}`;
}

// @file src/invoice.js
import { formatAmount, toMinorUnits } from './currency.js';
import { createId } from './ids.js';
import { lineTotal, linesByAmount, subtotal } from './line-items.js';

/**
 * Builds an invoice from line items. A coupon is { percentOff } from 0 to 100, or { amountOff } in minor units
 * of the invoice currency.
 */
export function buildInvoice({ items, currency, coupon = null }) {
  const amount = subtotal(items);
  const discount = discountFor(coupon, amount, currency);
  const total = Math.max(0, amount - discount);
  return {
    id: createId('inv'),
    currency,
    lines: linesByAmount(items).map((item) => ({
      name: item.name,
      quantity: item.quantity,
      amount: lineTotal(item),
    })),
    subtotal: amount,
    discount,
    total,
    formattedTotal: formatAmount(total, currency),
  };
}

function discountFor(coupon, amount, currency) {
  if (!coupon) return 0;
  if (coupon.percentOff) return Math.round((amount * coupon.percentOff) / 100);
  return Math.min(amount, toMinorUnits(coupon.amountOff, currency));
}

// @file src/payments.js
import { createId } from './ids.js';

// Network trouble is worth another try; a declined card or a bad request is not.
const RETRYABLE = new Set(['timeout', 'network_error', 'rate_limited']);

/**
 * Charges an invoice through the API client and retries the failures worth retrying. The client's createCharge
 * resolves to the charge, or rejects with an error that has a code.
 */
export async function payInvoice(client, invoice, { retries = 2 } = {}) {
  for (let attempt = 0; ; attempt += 1) {
    try {
      return await client.createCharge({
        amount: invoice.total,
        currency: invoice.currency,
        invoiceId: invoice.id,
        idempotencyKey: createId('pay'),
      });
    } catch (error) {
      if (!RETRYABLE.has(error?.code) || attempt >= retries) throw error;
    }
  }
}

