import { formatAmount, toMinorUnits } from './src/currency.js';
import { buildInvoice } from './src/invoice.js';
import { payInvoice } from './src/payments.js';

const cart = () => [
  { name: 'Pen', unitAmount: 250, quantity: 4 },
  { name: 'Notebook', unitAmount: 1999, quantity: 1 },
];

describe('currency', () => {
  test('converts a typed amount to minor units without losing a cent', () => {
    expect(toMinorUnits(19.99, 'usd')).toBe(1999);
    expect(toMinorUnits(0.29, 'eur')).toBe(29);
  });

  test('keeps zero-decimal currencies whole', () => {
    expect(toMinorUnits(500, 'jpy')).toBe(500);
    expect(formatAmount(500, 'jpy')).toBe('¥500');
  });
});

describe('invoice', () => {
  test('takes an amount-off coupon in minor units', () => {
    const invoice = buildInvoice({ items: cart(), currency: 'usd', coupon: { amountOff: 500 } });
    expect(invoice.subtotal).toBe(2999);
    expect(invoice.discount).toBe(500);
    expect(invoice.total).toBe(2499);
    expect(invoice.formattedTotal).toBe('$24.99');
  });

  test('lists lines largest first without reordering the cart it was given', () => {
    const items = cart();
    const invoice = buildInvoice({ items, currency: 'usd' });
    expect(invoice.lines.map((line) => line.name)).toEqual(['Notebook', 'Pen']);
    expect(items.map((item) => item.name)).toEqual(['Pen', 'Notebook']);
  });
});

describe('payments', () => {
  // The first attempt fails with the given code and the next one succeeds; every request is recorded.
  const flakyClient = (code) => {
    const requests = [];
    return {
      requests,
      async createCharge(request) {
        requests.push(request);
        if (requests.length === 1) throw Object.assign(new Error(code), { code });
        return { id: 'charge_1', status: 'succeeded', amount: request.amount };
      },
    };
  };

  test('retries a timeout with the same idempotency key', async () => {
    const client = flakyClient('timeout');
    const charge = await payInvoice(client, buildInvoice({ items: cart(), currency: 'usd' }));
    expect(charge.status).toBe('succeeded');
    expect(client.requests.length).toBe(2);
    expect(client.requests[1].idempotencyKey).toBe(client.requests[0].idempotencyKey);
  });

  test('does not retry a declined card', async () => {
    const client = flakyClient('card_declined');
    await expect(payInvoice(client, buildInvoice({ items: cart(), currency: 'usd' }))).rejects.toThrow('card_declined');
    expect(client.requests.length).toBe(1);
  });
});

