 * Builds an invoice from line items. A coupon is { percentOff } from 0 to 100, or { amountOff } in minor units
 * of the invoice currency.
 */
export function buildInvoice({ items, currency, coupon = null }) {
  const amount = subtotal(items);
  const discount = discountFor(coupon, amount);
  const total = Math.max(0, amount - discount);
  return {
    id: createId('inv'),
    currency,
    lines: linesByAmount(items).map((item) => ({
      name: item.name,
      quantity: item.quantity,
      amount: lineTotal(item),
    })),
    subtotal: amount,
    discount,
    total,
    formattedTotal: formatAmount(total, currency),
  };
}

function discountFor(coupon, amount) {
  if (!coupon) return 0;
  if (coupon.percentOff) return Math.round((amount * coupon.percentOff) / 100);
  // amountOff is already in minor units; converting it again made a 500-cent coupon worth 50,000.
  return Math.min(amount, coupon.amountOff ?? 0);
}

// @file src/payments.js
import { createId } from './ids.js';

// Network trouble is worth another try; a declined card or a bad request is not.
const RETRYABLE = new Set(['timeout', 'network_error', 'rate_limited']);

/**
 * Charges an invoice through the API client and retries the failures worth retrying. The client's createCharge
 * resolves to the charge, or rejects with an error that has a code.
 */
export async function payInvoice(client, invoice, { retries = 2 } = {}) {
  // One key for every attempt: a retry after a timeout must not become a second charge.
  const idempotencyKey = createId('pay');
  for (let attempt = 0; ; attempt += 1) {
    try {
      return await client.createCharge({
        amount: invoice.total,
        currency: invoice.currency,
        invoiceId: invoice.id,
        idempotencyKey,
      });
    } catch (error) {
      if (!RETRYABLE.has(error?.code) || attempt >= retries) throw error;
    }
  }
}

