// Monthly budget summary for the household dashboard.
// Written by our summer intern; a few users say the numbers look off.
export default function summarizeBudget(monthlyIncome, expenses, limits) {
  const totals = {};
  for (let i = 0; i < expenses.length; i++) {
    const { category, amount, frequency } = expenses[i];
    let monthly = amount;
    if (frequency === 'weekly') monthly = amount * 4;
    if (frequency === 'yearly') monthly = amount / 12;
    totals[category] = (totals[category] || 0) + monthly;
  }

  let spent = 0;
  const overLimit = [];
  for (const category in totals) {
    spent += totals[category];
    if (limits[category] && totals[category] > limits[category]) {
      overLimit.push(category);
    }
  }

  const remaining = monthlyIncome - spent;
  const savingsRate = Math.round((remaining / monthlyIncome) * 100);
  return { totals, spent, remaining, savingsRate, overLimit };
}

