// Monthly budget summary for the household dashboard.
// A weekly expense happens 52 times a year, money adds up in whole cents, a limit of 0 counts,
// and a month without income saves nothing.
const WEEKS_PER_YEAR = 52;
const MONTHS_PER_YEAR = 12;

function monthlyCents(amount, frequency) {
  const cents = amount * 100;
  if (frequency === 'weekly') return Math.round((cents * WEEKS_PER_YEAR) / MONTHS_PER_YEAR);
  if (frequency === 'yearly') return Math.round(cents / MONTHS_PER_YEAR);
  return Math.round(cents);
}

export default function summarizeBudget(monthlyIncome, expenses, limits) {
  const totalCents = {};
  for (const { category, amount, frequency } of expenses) {
    totalCents[category] = (totalCents[category] || 0) + monthlyCents(amount, frequency);
  }

  let spentCents = 0;
  const totals = {};
  const overLimit = [];
  for (const category of Object.keys(totalCents)) {
    spentCents += totalCents[category];
    totals[category] = totalCents[category] / 100;
    if (limits[category] !== undefined && totals[category] > limits[category]) {
      overLimit.push(category);
    }
  }

  const remainingCents = Math.round(monthlyIncome * 100) - spentCents;
  const remaining = remainingCents / 100;
  const savingsRate = monthlyIncome > 0 ? Math.round((remaining / monthlyIncome) * 100) : 0;
  return { totals, spent: spentCents / 100, remaining, savingsRate, overLimit };
}

